 if($method==='POST'&&preg_match('~/api/repair/send/?$~',$path)){$pid=(int)($body['productId']??0);$qty=(int)($body['quantity']??0);$date=trim((string)($body['date']??''));$submitted=trim((string)($body['submittedBy']??''));$issue=trim((string)($body['issueDescription']??''));$shop=trim((string)($body['repairShop']??''))?:'کارگاه تعمیرات داخلی';if($pid<=0||$qty<=0||$date===''||$submitted===''||$issue==='')throw new BusinessError('اطلاعات ارسال به تعمیر ناقص است');$row=$db->transaction(function(Database $db)use($pid,$qty,$date,$submitted,$issue,$shop,$user){$p=$db->one('SELECT * FROM products WHERE id=? FOR UPDATE',[$pid]);if(!$p)throw new BusinessError('کالا یافت نشد',404);if(!(int)$p['active'])throw new BusinessError('این کالا بایگانی شده است');$snap=(new Business($db))->stockSnapshot($p);if($qty>$snap['available'])throw new BusinessError('تعداد قابل ارسال به تعمیر کافی نیست');$b=new Business($db);$doc=$b->nextDocNumber('repIn');$now=gmdate('c');$db->execute("INSERT INTO repair_records (doc_number,product_id,quantity,send_date,submitted_by,repair_shop,issue_description,status,created_by_user_id,created_at) VALUES (?,?,?,?,?,?,?,'در حال تعمیر',?,?)",[$doc,$pid,$qty,$date,$submitted,$shop,$issue,$user['id'],$now]);return $db->one('SELECT * FROM repair_records WHERE id=?',[$db->lastInsertId()]);});jsonResponse(['repairRecord'=>repairRow($row)],201);}
